using LifeVerse.Api.Modules.Inventory;
using System.IdentityModel.Tokens.Jwt;
using System.Security.Cryptography;
using System.Text.Json;
using LifeVerse.Api.Data;
using LifeVerse.Api.Modules.Worlds;
using Microsoft.EntityFrameworkCore;

namespace LifeVerse.Api.Modules.Assets;

public sealed record AssetPermissionRequest(Guid? UserId, Guid? GroupId, string PrincipalType, string Flags);
public sealed record InventoryFolderRequest(string Name, Guid? ParentId);
public sealed record InventoryItemUpdateRequest(string? DisplayName, Guid? FolderId, bool? IsFavorite = null, bool? ClearFolder = null);
public sealed record PlaceAssetRequest(Guid IslandId, float PositionX, float PositionY, float PositionZ, float RotationX, float RotationY, float RotationZ);
public sealed record EquipAssetRequest(string Slot);

public static class AssetEndpoints
{
    public static IEndpointRouteBuilder MapAssetEndpoints(this IEndpointRouteBuilder endpoints)
    {
        endpoints.MapMeshAssetEndpoints();
        endpoints.MapInventoryOrganizerEndpoints();
        var assets = endpoints.MapGroup("/api/v1/assets").WithTags("Assets").RequireAuthorization(); assets.MapPost("/upload", UploadAsync).DisableAntiforgery(); assets.MapGet("/{assetId:guid}/download", DownloadAsync); assets.MapPost("/{assetId:guid}/permissions", GrantPermissionAsync);
        var inventory = endpoints.MapGroup("/api/v1/inventory").WithTags("Inventory").RequireAuthorization(); inventory.MapPatch("/items/{itemId:guid}", UpdateItemAsync); inventory.MapPost("/items/{itemId:guid}/favorite", FavoriteAsync); inventory.MapDelete("/items/{itemId:guid}/favorite", UnfavoriteAsync); inventory.MapDelete("/items/{itemId:guid}", DeleteItemAsync); inventory.MapPost("/items/{itemId:guid}/restore", RestoreItemAsync); inventory.MapPost("/items/{itemId:guid}/copy", CopyItemAsync); inventory.MapPost("/items/{itemId:guid}/place", PlaceAsync); inventory.MapPost("/items/{itemId:guid}/equip", EquipAsync);
        return endpoints;
    }

    private static async Task<IResult> UploadAsync(HttpRequest request, HttpContext context, LifeVerseDbContext db, AssetStorageService storage, TimeProvider clock, CancellationToken ct)
    {
        if (!TryUser(context, out var owner)) return Results.Unauthorized(); var form = await request.ReadFormAsync(ct); var file = form.Files.GetFile("file"); var category = form["category"].ToString().Trim().ToLowerInvariant(); var allowedCategories = new[] { "objects", "textures", "sounds", "animations", "clothing", "accessories", "models" }; if (file is null || file.Length == 0 || file.Length > 100 * 1024 * 1024 || !allowedCategories.Contains(category)) return Results.BadRequest(new { error = "A file and a valid category are required and must be no larger than 100 MB." });
        await using var input = file.OpenReadStream(); using var memory = new MemoryStream(); await input.CopyToAsync(memory, ct); var bytes = memory.ToArray(); var inspection = await AssetValidator.InspectAsync(file.FileName, file.ContentType, bytes, ct); if (!inspection.Valid) return Results.ValidationProblem(new Dictionary<string, string[]> { ["file"] = [inspection.Error!] }); var hash = Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(); var duplicate = await db.AssetVersions.AsNoTracking().Include(x => x.Asset).SingleOrDefaultAsync(x => x.ContentHash == hash && x.Asset.DeletedAt == null, ct); if (duplicate is not null) { var nowDuplicate = clock.GetUtcNow(); db.InventoryItems.Add(new InventoryItem { Id = Guid.NewGuid(), OwnerUserId = owner, AssetId = duplicate.AssetId, DisplayName = duplicate.Asset.Name, CreatedAt = nowDuplicate, UpdatedAt = nowDuplicate }); await db.SaveChangesAsync(ct); return Results.Ok(new { assetId = duplicate.AssetId, reused = true, hash }); }
        var now = clock.GetUtcNow(); var name = Path.GetFileNameWithoutExtension(file.FileName); if (string.IsNullOrWhiteSpace(name)) name = "asset"; name = new string(name.Where(ch => char.IsLetterOrDigit(ch) || ch is ' ' or '-' or '_').ToArray()).Trim(); if (name.Length == 0) name = "asset"; var asset = new Asset { Id = Guid.NewGuid(), OwnerUserId = owner, CreatorUserId = owner, Name = name[..Math.Min(name.Length, 160)], Category = category, Description = string.Empty, LicenseJson = "{\"source\":\"user-upload\",\"moderation\":\"pending\"}", Status = "ready", CreatedAt = now, UpdatedAt = now }; var key = await storage.PutAsync(owner, hash, bytes, ct); var version = new AssetVersion { Id = Guid.NewGuid(), AssetId = asset.Id, Version = 1, ContentHash = hash, StorageKey = key, MimeType = inspection.MimeType, ByteSize = bytes.Length, Width = inspection.Width, Height = inspection.Height, DurationSeconds = inspection.DurationSeconds, ValidationJson = inspection.MetadataJson, CreatedAt = now }; db.Assets.Add(asset); db.AssetVersions.Add(version); db.InventoryItems.Add(new InventoryItem { Id = Guid.NewGuid(), OwnerUserId = owner, AssetId = asset.Id, DisplayName = asset.Name, CreatedAt = now, UpdatedAt = now }); await db.SaveChangesAsync(ct); return Results.Created($"/api/v1/assets/{asset.Id}", new { assetId = asset.Id, version = 1, hash, category, mimeType = inspection.MimeType, width = inspection.Width, height = inspection.Height, metadata = inspection.MetadataJson });
    }



    internal static async Task<IResult> UpdateItemAsync(Guid itemId, InventoryItemUpdateRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null && x.Status == "active", ct); if (item is null) return Results.NotFound(); if (request.DisplayName is not null) item.DisplayName = request.DisplayName.Trim()[..Math.Min(request.DisplayName.Trim().Length, 160)]; if (request.FolderId is not null || request.ClearFolder == true) { if (request.FolderId is { } target && !await InventoryOrganizer.OwnFolderAsync(db, owner, target, ct)) return Results.NotFound(); item.FolderId = request.FolderId; } if (request.IsFavorite is not null) item.IsFavorite = request.IsFavorite.Value; item.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(item); }
    private static async Task<IResult> FavoriteAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => await SetFavoriteAsync(itemId, true, context, db, clock, ct);
    private static async Task<IResult> UnfavoriteAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) => await SetFavoriteAsync(itemId, false, context, db, clock, ct);
    private static async Task<IResult> SetFavoriteAsync(Guid itemId, bool value, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null && x.Status == "active", ct); if (item is null) return Results.NotFound(); item.IsFavorite = value; item.UpdatedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.Ok(new { itemId, favorite = value }); }
    internal static async Task<IResult> DeleteItemAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null && x.Status == "active", ct); if (item is null) return Results.NotFound(); item.DeletedAt = clock.GetUtcNow(); await db.SaveChangesAsync(ct); return Results.NoContent(); }
    internal static async Task<IResult> RestoreItemAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.Status == "active", ct); if (item is null) return Results.NotFound(); /* an item used up by placing it in the world is not in the bin: it cannot be brought back */ item.DeletedAt = null; item.DeletedWithFolderId = null; if (item.FolderId is { } at && !await InventoryOrganizer.OwnFolderAsync(db, owner, at, ct)) item.FolderId = null; /* its folder is gone: back to the top level */ item.UpdatedAt = DateTimeOffset.UtcNow; await db.SaveChangesAsync(ct); return Results.Ok(item); }
    private static async Task<IResult> CopyItemAsync(Guid itemId, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var result = await ItemTransfers.CopyAsync(db, owner, itemId, clock.GetUtcNow(), ct); return result.Ok ? Results.Ok(result.Item) : result.Error switch { "not_found" => Results.NotFound(), "inventory_full" => Results.Conflict(new { error = result.Error }), _ => Results.Json(new { error = result.Error }, statusCode: StatusCodes.Status403Forbidden) }; }
    private static async Task<IResult> GrantPermissionAsync(Guid assetId, AssetPermissionRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var asset = await db.Assets.SingleOrDefaultAsync(x => x.Id == assetId && x.OwnerUserId == owner && x.DeletedAt == null, ct); if (asset is null) return Results.NotFound(); if (request.PrincipalType is not ("user" or "group") || request.Flags.Length > 256) return Results.BadRequest(); var permission = new AssetPermission { Id = Guid.NewGuid(), AssetId = assetId, UserId = request.UserId, GroupId = request.GroupId, PrincipalType = request.PrincipalType, Flags = request.Flags.ToLowerInvariant(), CreatedAt = clock.GetUtcNow() }; db.AssetPermissions.Add(permission); await db.SaveChangesAsync(ct); return Results.Ok(permission); }
    private static async Task<IResult> DownloadAsync(Guid assetId, HttpContext context, LifeVerseDbContext db, AssetStorageService storage, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var asset = await db.Assets.AsNoTracking().SingleOrDefaultAsync(x => x.Id == assetId && x.DeletedAt == null, ct); if (asset is null) return Results.NotFound(); if (asset.OwnerUserId != owner && !await db.AssetPermissions.AnyAsync(x => x.AssetId == assetId && x.UserId == owner && x.RevokedAt == null && (x.Flags.Contains("use") || x.Flags.Contains("copy")), ct)) return Results.Forbid(); var wanted = asset.OwnerUserId == owner && int.TryParse(context.Request.Query["version"], out var asked) ? asked : asset.CurrentVersion; /* the creator can fetch any of the versions */ var version = await db.AssetVersions.AsNoTracking().SingleOrDefaultAsync(x => x.AssetId == assetId && x.Version == wanted, ct); if (version is null) return Results.NotFound(); var stream = await storage.OpenReadAsync(version.StorageKey, ct); return stream is null ? Results.NotFound() : Results.File(stream, version.MimeType, asset.Name + Path.GetExtension(version.StorageKey)); }
    internal static async Task<IResult> EquipAsync(Guid itemId, EquipAssetRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.AsNoTracking().SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null && x.Status == "active", ct); if (item is null) return Results.NotFound(); var avatar = await db.Avatars.Include(x => x.EquippedItems).SingleOrDefaultAsync(x => x.UserId == owner, ct); if (avatar is null) return Results.NotFound(); var slot = request.Slot.Trim().ToLowerInvariant(); var existing = avatar.EquippedItems.SingleOrDefault(x => x.Slot == slot); if (existing is null) db.EquippedItems.Add(new EquippedItem { Id = Guid.NewGuid(), AvatarId = avatar.Id, Slot = slot, ItemKey = $"asset:{item.AssetId}", TintColor = "#FFFFFF", EquippedAt = clock.GetUtcNow() }); else { existing.ItemKey = $"asset:{item.AssetId}"; existing.EquippedAt = clock.GetUtcNow(); } await db.SaveChangesAsync(ct); await InventoryOrganizer.TouchAsync(db, owner, itemId, clock.GetUtcNow(), ct); return Results.NoContent(); }
    internal static async Task<IResult> PlaceAsync(Guid itemId, PlaceAssetRequest request, HttpContext context, LifeVerseDbContext db, TimeProvider clock, CancellationToken ct) { if (!TryUser(context, out var owner)) return Results.Unauthorized(); var item = await db.InventoryItems.AsNoTracking().SingleOrDefaultAsync(x => x.Id == itemId && x.OwnerUserId == owner && x.DeletedAt == null && x.Status == "active", ct); if (item is null) return Results.NotFound(); if (!LifeVerse.Shared.Items.ItemRights.IsCopyable(item.OwnerRights)) return Results.Json(new { error = "use_rez" }, statusCode: StatusCodes.Status409Conflict); /* placing without using the item up would copy it: items that cannot be copied are placed by the server */ var island = await db.Islands.SingleOrDefaultAsync(x => x.Id == request.IslandId && x.DeletedAt == null, ct); if (island is null) return Results.NotFound(); if (island.OwnerUserId != owner && !await db.IslandPermissions.AnyAsync(x => x.IslandId == island.Id && x.UserId == owner && x.RevokedAt == null && (x.Permission == "build" || x.Permission == "admin"), ct)) return Results.Forbid(); var now = clock.GetUtcNow(); var placed = new WorldAssetInstance { Id = Guid.NewGuid(), IslandId = island.Id, AssetId = item.AssetId, OwnerUserId = owner, PositionX = request.PositionX, PositionY = request.PositionY, PositionZ = request.PositionZ, RotationX = request.RotationX, RotationY = request.RotationY, RotationZ = request.RotationZ, CreatedAt = now, UpdatedAt = now }; db.WorldAssetInstances.Add(placed); await db.SaveChangesAsync(ct); await InventoryOrganizer.TouchAsync(db, owner, itemId, now, ct); return Results.Created($"/api/v1/worlds/islands/{island.Id}/assets/{placed.Id}", placed); }
    private static bool TryUser(HttpContext context, out Guid id) => Guid.TryParse(context.User.FindFirst(JwtRegisteredClaimNames.Sub)?.Value, out id);
}
